UPDATE regular_season_games SET opening_odds = NULL WHERE id = 'CFB_2026-09-19_e401856802' AND json_extract(opening_odds, '$.captured_at') = (SELECT snapshot_time FROM odds_history WHERE id = 'CFB_2026-09-19_e401856802_draftkings_close');
INSERT INTO change_log (game_id, source, field, old_value, new_value) SELECT id, 'stage2_wrong_pair_repair', 'closing_odds', closing_odds, 'NULL: written by position from a swapped pairing; the sync rewrites it by team (docs/CC-CMD-2026-10-19-cfb-stage2-wrong-pair.md)' FROM regular_season_games WHERE id = 'CFB_2026-09-19_e401856802' AND json_extract(closing_odds, '$.captured_at') = (SELECT snapshot_time FROM odds_history WHERE id = 'CFB_2026-09-19_e401856802_draftkings_close');
UPDATE regular_season_games SET closing_odds = NULL WHERE id = 'CFB_2026-09-19_e401856802' AND json_extract(closing_odds, '$.captured_at') = (SELECT snapshot_time FROM odds_history WHERE id = 'CFB_2026-09-19_e401856802_draftkings_close');
